param([string]$Root = $PSScriptRoot)
$ErrorActionPreference = 'Stop'
$Root = [IO.Path]::GetFullPath($Root)
$inputDir = Join-Path $Root 'inputs'
$out = Join-Path $Root 'notes'
$archive = Join-Path $out 'archive'
[IO.Directory]::CreateDirectory($archive) | Out-Null
$lock = $null
try { $lock = [IO.File]::Open((Join-Path $out '.run.lock'),[IO.FileMode]::OpenOrCreate,[IO.FileAccess]::ReadWrite,[IO.FileShare]::None) }
catch { throw 'Another run is active. Wait for it to finish and try again.' }
try {
$utf8 = New-Object Text.UTF8Encoding($false, $true)
function Hash([byte[]]$bytes) {
    $sha = [Security.Cryptography.SHA256]::Create()
    try { return ([BitConverter]::ToString($sha.ComputeHash($bytes))).Replace('-','').ToLowerInvariant() } finally { $sha.Dispose() }
}
function WriteAtomic($path, $text) {
    $temp = "$path.tmp"
    [IO.File]::WriteAllText($temp, $text, (New-Object Text.UTF8Encoding($true)))
    if ([IO.File]::Exists($path)) { [IO.File]::Replace($temp, $path, "$path.previous") } else { [IO.File]::Move($temp, $path) }
}
function Esc($s) { return [Net.WebUtility]::HtmlEncode([string]$s) }
$results = @()
$created = 0; $skipped = 0; $failed = 0
if (!(Test-Path -LiteralPath $inputDir)) { throw 'inputs folder does not exist.' }
foreach ($file in @(Get-ChildItem -LiteralPath $inputDir -File -Recurse | Sort-Object FullName)) {
    $relative = $file.FullName.Substring($inputDir.Length + 1)
    try {
        if ($file.Extension.ToLowerInvariant() -notin @('.txt','.md')) { throw 'Only .txt and .md text files are supported.' }
        $bytes = [IO.File]::ReadAllBytes($file.FullName)
        $hash = Hash $bytes
        $pathHash = Hash ($utf8.GetBytes($relative))
        $id = "$pathHash-$hash"
        $recordPath = Join-Path $archive "$id.json"
        if (Test-Path -LiteralPath $recordPath) {
            $record = Get-Content -LiteralPath $recordPath -Raw -Encoding UTF8 | ConvertFrom-Json
            if (!(Test-Path -LiteralPath (Join-Path $archive "$id.txt"))) { throw 'Archived original is missing; restore it before retrying.' }
            $skipped++
        } else {
            $offset = 0
            if ($bytes.Length -ge 3 -and $bytes[0] -eq 239 -and $bytes[1] -eq 187 -and $bytes[2] -eq 191) { $offset = 3 }
            if ($bytes.Length -ge 2 -and $bytes[0] -eq 255 -and $bytes[1] -eq 254) {
                $decoder = New-Object Text.UnicodeEncoding($false,$true,$true); $offset = 2
            } elseif ($bytes.Length -ge 2 -and $bytes[0] -eq 254 -and $bytes[1] -eq 255) {
                $decoder = New-Object Text.UnicodeEncoding($true,$true,$true); $offset = 2
            } else { $decoder = $utf8 }
            $source = $decoder.GetString($bytes,$offset,$bytes.Length-$offset)
            if ([string]::IsNullOrWhiteSpace($source)) { throw 'Empty text file.' }
            if ($source -match '[\x00-\x08\x0B\x0C\x0E-\x1F]') { throw 'Binary/control characters found in text.' }
            $lines = @($source -split '\r\n|\n|\r')
            $items = @()
            for ($i=0; $i -lt $lines.Count; $i++) {
                $line = $lines[$i].Trim()
                if (!$line -or $line -match '^(会议|日期)[:：]') { continue }
                $category = '讨论 / 原文摘录'
                if ($line -match '^(决定|决议)[:：]') { $category = '决定（原文明确）' }
                elseif ($line -match '(未定|未确定|尚未批准|未批准|建议|希望)') { $category = '未定 / 建议（未视为决定）' }
                elseif ($line -match '^待办[:：]') { $category = '待办（按原文保留）' }
                $items += [pscustomobject]@{line=$i+1; category=$category; text=$line}
            }
            $record = [pscustomobject]@{version=1; id=$id; path=$relative; sha256=$hash; processed=(Get-Date).ToString('o'); lines=$lines; items=$items}
            # Commit the preserved source before the record. A retry reuses the same identifiers.
            [IO.File]::WriteAllBytes((Join-Path $archive "$id.txt"),$bytes)
            WriteAtomic $recordPath ($record | ConvertTo-Json -Depth 8)
            $created++
        }
        $results += [pscustomobject]@{path=$relative; ok=$true; record=$record; error=''}
    } catch {
        $failed++
        $results += [pscustomobject]@{path=$relative; ok=$false; record=$null; error=$_.Exception.Message}
    }
}
$html = New-Object Text.StringBuilder
[void]$html.Append(@'
<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>会议笔记</title>
<style>body{font:16px/1.7 system-ui,sans-serif;max-width:1000px;margin:35px auto;padding:0 20px;color:#233044;background:#f5f7fa}article{background:white;padding:22px;margin:20px 0;border-radius:12px;border:1px solid #dce2ea}input{padding:12px;width:85%;font:inherit}a{color:#135baa}pre{white-space:pre-wrap;word-break:break-word}small{color:#576779}.error{color:#a22222}li{margin:10px 0}:target{background:#fff2a6}summary{cursor:pointer}</style>
<h1>会议笔记</h1><p>本地规则摘录；没有调用 AI 或外部服务。保留原句，不推断负责人、日期或批准状态。各会议按来源独立呈现，冲突不会自动合并。</p>
<input id="search" aria-label="搜索笔记和原文" placeholder="搜索笔记和原文…"><p id="count"></p>
'@)
[void]$html.Append("<p>本次：新增 $created，跳过 $skipped，失败 $failed。更新时间：$(Esc ((Get-Date).ToString('yyyy-MM-dd HH:mm:ss')))</p>")
foreach ($result in $results) {
    [void]$html.Append("<article><h2>$(Esc $result.path)</h2>")
    if (!$result.ok) {
        [void]$html.Append("<p class='error'>未处理：$(Esc $result.error)</p><p>修复文件后再次运行即可；其他文件已独立处理。历史成果仍保存在 archive 文件夹。</p></article>")
        continue
    }
