    # Quoted vocabulary is not evidence of the sentence's approval status.
    $evidence = $line -replace '\u201c[^\u201d]*\u201d|「[^」]*」|『[^』]*』|"[^"]*"|\u2018[^\u2019]*\u2019', ''
    $pending = '(未定|未确定|未确认|未批准|未决定|尚未|还没|还未|尚待|仍待|待.*(确认|批准|审批|决定|评估)|没有.*(定下|确认|批准|决定)|有待|暂定|拟议|提议|建议|希望|考虑|可能|也许|是否|能否|要不要|如果|若|假如|除非|取决于|以.*为准|[？?])'
    if ($evidence -match $pending) { return '未定 / 建议（未视为决定）' }
    if ($evidence -match '^(决定|决议)[:：]') {
