artifacts.tests.ps1:
$ErrorActionPreference = 'Stop'
function Assert($condition, $message) { if (!$condition) { throw $message } }
$workspace = [IO.Path]::GetFullPath($PSScriptRoot)
$testRoot = Join-Path $workspace ('.verification-' + [Guid]::NewGuid().ToString('N'))
$encoding = New-Object Text.UTF8Encoding($true)
function Put($name, $text) { [IO.File]::WriteAllText((Join-Path "$testRoot/inputs" $name), $text, $encoding) }
function Records { @(Get-ChildItem "$testRoot/notes/archive/*.json" | ForEach-Object { Get-Content $_.FullName -Raw -Encoding UTF8 | ConvertFrom-Json }) }
function Run { & "$workspace/organize.ps1" -Root $testRoot }
try {
    [IO.Directory]::CreateDirectory("$testRoot/inputs") | Out-Null
    [IO.Directory]::CreateDirectory("$testRoot/notes/archive") | Out-Null
    Copy-Item "$workspace/inputs/*" "$testRoot/inputs"
    Copy-Item "$workspace/notes/archive/*" "$testRoot/notes/archive"
    # Recreate stale classifications even after the real workspace has been repaired.
    foreach ($file in Get-ChildItem "$testRoot/notes/archive/*.json") {
        $r = Get-Content $file.FullName -Raw -Encoding UTF8 | ConvertFrom-Json
        $r.version = 1
        foreach ($item in $r.items) { $item.category = '决定（原文明确）' }
        [IO.File]::WriteAllText($file.FullName, ($r | ConvertTo-Json -Depth 8), $encoding)
    }
    $originals = @{}
    foreach ($file in Get-ChildItem "$testRoot/notes/archive/*.txt") { $originals[$file.Name] = (Get-FileHash $file.FullName).Hash }
    Run
    $records = Records
    Assert ($records.Count -eq 4) 'Migration duplicated records.'
    foreach ($r in $records) {
        $expected = if ($r.path -in @('pending.txt','question.txt')) { '未定 / 建议（未视为决定）' } else { '决定（原文明确）' }
        Assert ($r.version -eq 2 -and $r.items[0].category -eq $expected) "Wrong migrated category: $($r.path)"
        Assert ((Get-FileHash "$testRoot/notes/archive/$($r.id).txt").Hash -eq $originals["$($r.id).txt"]) 'Migration changed original bytes.'
    }
    $cases = @(
        @('决定：计划尚未批准。', '未定 / 建议（未视为决定）'),
        @('决议：建议先试用。', '未定 / 建议（未视为决定）'),
        @('决定：是否调整时间？', '未定 / 建议（未视为决定）'),
        @('决定：上线时间还没定。', '未定 / 建议（未视为决定）'),
        @('决定：方案暂定，待审批。', '未定 / 建议（未视为决定）'),
        @('决定：如果批准，下周上线。', '未定 / 建议（未视为决定）'),
        @('决定：不得公开手机号。', '决定（原文明确）'),
        @('决议：禁止导出个人信息。', '决定（原文明确）'),
        @('待办：小李周五提交资料。', '待办（按原文保留）'),
        @('讨论：首版提供活动报名。', '讨论 / 原文摘录'),
        @('决定：不增加预算。', '决定（原文明确）')
    )
    $text = "会议：规则回归`r`n日期：2026-10-12`r`n" + (($cases | ForEach-Object { $_[0] }) -join "`r`n") + "`r`n<script>&"
    Put 'cases.md' $text
    [IO.File]::WriteAllBytes("$testRoot/inputs/bad.txt", [byte[]]@(255,0,255))
    Run
    $status = Get-Content "$testRoot/notes/status.json" -Raw -Encoding UTF8 | ConvertFrom-Json
    Assert (@($status | Where-Object { !$_.success }).Count -eq 1) 'Bad input was not isolated.'
    Assert (@($status | Where-Object { $_.path -eq 'bad.txt' -and !$_.success }).Count -eq 1) 'Missing bad-file status.'
    $r = Records | Where-Object { $_.path -eq 'cases.md' }
    for ($i=0; $i -lt $cases.Count; $i++) {
        Assert ($r.items[$i].category -eq $cases[$i][1]) "Wrong category: $($cases[$i][0])"
        Assert ($r.items[$i].text -eq $cases[$i][0] -and $r.items[$i].line -eq $i+3) 'Text or line provenance changed.'
    }
    $html = Get-Content "$testRoot/notes/index.html" -Raw -Encoding UTF8
    Assert ($html.Contains('&lt;script&gt;&amp;')) 'Source was not HTML escaped.'
    foreach ($r in (Records)) {
        Assert ((Get-FileHash "$testRoot/inputs/$($r.path)").Hash -eq (Get-FileHash "$testRoot/notes/archive/$($r.id).txt").Hash) 'Original byte preservation failed.'
        foreach ($item in $r.items) {
            Assert ($html.Contains("href='#s-$($r.id)-$($item.line)'")) 'Source link missing.'
            Assert ($html.Contains("id='s-$($r.id)-$($item.line)'")) 'Source link target missing.'
        }
    }
    $snapshot = @{}
    foreach ($file in Get-ChildItem "$testRoot/notes/archive/*.json") { $snapshot[$file.Name] = (Get-FileHash $file.FullName).Hash }
    Run
    Assert ((Records).Count -eq $snapshot.Count) 'Repeated run duplicated records.'
    foreach ($file in Get-ChildItem "$testRoot/notes/archive/*.json") { Assert ((Get-FileHash $file.FullName).Hash -eq $snapshot[$file.Name]) 'Repeated run rewrote records.' }
    Put 'bad.txt' '决定：预算待负责人确认。'
    Run
    $status = Get-Content "$testRoot/notes/status.json" -Raw -Encoding UTF8 | ConvertFrom-Json
    Assert (@($status | Where-Object { !$_.success }).Count -eq 0) 'Fixed file was not retried successfully.'
    Assert ((Records | Where-Object { $_.path -eq 'bad.txt' }).items[0].category -eq '未定 / 建议（未视为决定）') 'Retry classification failed.'
    $old = Records | Where-Object { $_.path -eq 'settled.txt' }
    Put 'settled.txt' '决定：新版上线日期待确认。'
    Run
    Assert ((Records | Where-Object { $_.path -eq 'settled.txt' }).Count -eq 2) 'Changed input history was lost.'
    Assert (Test-Path "$testRoot/notes/archive/$($old.id).txt") 'Historical source lost.'
    Write-Host 'PASS: stale-cache migration, uncertainty/prohibitions, original bytes, source links, escaping, repeat runs, bad-file retry, changed-input history.'
} finally {
    # Delete only the unique directory created by this test inside this workspace.
    $resolved = [IO.Path]::GetFullPath($testRoot)
    if ($resolved.StartsWith($workspace + [IO.Path]::DirectorySeparatorChar) -and (Split-Path $resolved -Leaf) -match '^\.verification-[a-f0-9]{32}$') {
        if (Test-Path -LiteralPath $resolved) { Remove-Item -LiteralPath $resolved -Recurse -Force }
    }
}
